export const messages=Object.fromEntries(Object.entries(copy).map(([group,items])=>[group,items.map(([title,text],i)=>({id:group+'-'+i,group,title,text}))]));
export const messageCount=Object.values(messages).reduce((n,items)=>n+items.length,0);
export function createDeck(random=Math.random){const bags=new Map();let previous='';return group=>{group=messages[group]?group:'gentle';let bag=bags.get(group);if(!bag?.length){bag=[...messages[group]];for(let i=bag.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}if(bag.length>1&&bag[bag.length-1].id===previous)[bag[0],bag[bag.length-1]]=[bag[bag.length-1],bag[0]];bags.set(group,bag)}const result=bag.pop();previous=result.id;return result}}
